/*
 * src: /app/root/planejamento/static/hiring/configuration/MinuteConfiguration.js
 */

Ext._define('planning.hiring.configuration.MinuteConfiguration', {
    extend: 'toolkit.widget.TabPanel',

    dataReload: function() {
        this._config = core.nullValue(this.config, {});

        Ext.Ajax.request({
            url: core.callAction('PHMMinuteConfiguration', 'dataReload'),
            scope: this,
            success: function(xhr) {
                var rst = Ext.decode(xhr.responseText);

                if(rst.success) {
                    this.updatePanels(
                        rst.config.jobPosition,
                        false
                    );

                    this.getFormPanel().getForm().setValues(rst.config);
                }
            }
        });
    },

    saveConfiguration: function() {
        Ext.Ajax.request({
            url: core.callAction('PHMMinuteConfiguration', 'save'),
            scope: this,
            params: this.getFormPanel().getForm().getValues(),
            success: function(xhr) {
                var rst = Ext.decode(xhr.responseText);
                var message, tipo;

                if(rst.success) {
                    message = 'Configurações persistidas com sucesso';
                    tipo = Ext.Msg.INFO;
                }
                else {
                    tipo = Ext.Msg.ERROR;
                    message = rst.message;
                }

                Ext.Msg.show({
                    title: 'Gravando configurações',
                    icon: tipo,
                    buttons: Ext.Msg.OK,
                    msg: message
                });
            }
        });
    },

    updatePanels: function(value, persist) {
        persist = core.nullValue(persist, true);

        if(value !== undefined) {
            this.getSelectedJobPositionGrid().setFilterProperty('pk__in', value, 1000);
            this.getAvailableJobPositionGrid().setFilterProperty('pk__in', value, -1000);

            this._updatePanels = value;

            if(persist) {
                Ext.Ajax.request({
                    url: core.callAction('PHMMinuteConfiguration', 'write'),
                    params: {
                        property: 'jobPosition',
                        value: Ext.encode(this._updatePanels)
                    }
                });
            }
        }

        return this._updatePanels;
    },

    addJobPosition: function(selected) {
        selected = core.nullValue(
            selected,
            this.getAvailableJobPositionGrid().getSelectionModel().getSelections().map(
                function(data) {
                    return data.get('pk');
                }
            )
        );

        if(selected.length > 0) {
            selected = selected.concat(this.updatePanels());
            this.updatePanels(selected);
        }
        else
            Ext.Msg.show({
                'title': 'Adicionando',
                'icon': Ext.Msg.ERROR,
                'buttons': Ext.Msg.OK,
                'msg': 'Primeiro selecione os itens a serem adicionados.'
            });
    },

    addAllJobPosition: function() {
        var selected = [];

        this.getAvailableJobPositionGrid().getStore().each(
            function(data) {
                selected.push(data.get('pk'));
            }
        );

        this.addJobPosition(selected);
    },

    removeJobPosition: function(selected) {
        selected = core.nullValue(
            selected,
            this.getSelectedJobPositionGrid().getSelectionModel().getSelections().map(
                function(data) {
                    return data.get('pk');
                }
            )
        );

        if(selected.length > 0) {
            var value = this.updatePanels();
            selected.map(function(pk) { value.remove(pk); });
            this.updatePanels(value);
        }
        else
            Ext.Msg.show({
                'title': 'Removendo',
                'icon': Ext.Msg.ERROR,
                'buttons': Ext.Msg.OK,
                'msg': 'Primeiro selecione os itens a serem removidos.'
            });
    },

    removeAllJobPosition: function() {
        var selected = [];

        this.getSelectedJobPositionGrid().getStore().each(
            function(data) {
                selected.push(data.get('pk'));
            }
        );

        this.removeJobPosition(selected);
    },

    getAvailableJobPositionGrid: function() {
        var self = this;

        if(!this._availableJobPosition) {
            this._availableJobPosition = Ext._create('rh.jobposition.Grid', {
                title: 'Disponíveis',
                border: true,
                flex: 1,
                doubleClickHandler: function() { self.addJobPosition(); },
                gridAutoLoad: false,
                columnAction: false,
                configOrderToolBar: ['search'],
                hideColumns: [
                    'ativo',
                    'unidade_administrativa_unicode',
                    'lotacao_responsavel_unicode',
                    'chefia',
                    'substituivel',
                    'tipo_lei_cargo_display',
                    'indicativo_display',
                    'codigo',
                    'acumulavel'
                ],
            });

            // this._availableJobPosition.setFilterProperty('pk__in', core.nullValue(this._values.updatePanels, []), -1000, false);
            this._availableJobPosition.setFilterProperty('ativo', true, 1001, false);
        }

        return this._availableJobPosition;
    },

    getSelectedJobPositionGrid: function() {
        var self = this;

        if(!this._selectedJobPosition) {
            this._selectedJobPosition = Ext._create('rh.jobposition.Grid', {
                title: 'Selecionados',
                border: true,
                flex: 1,
                doubleClickHandler: function() { self.removeJobPosition(); },
                gridAutoLoad: false,
                columnAction: false,
                configOrderToolBar: ['search'],
                hideColumns: [
                    'ativo',
                    'unidade_administrativa_unicode',
                    'lotacao_responsavel_unicode',
                    'chefia',
                    'substituivel',
                    'tipo_lei_cargo_display',
                    'indicativo_display',
                    'codigo',
                    'acumulavel'
                ],
            });

            // this._selectedJobPosition.setFilterProperty('pk__in', core.nullValue(this._values.updatePanels, []), 1000, false);
        }

        return this._selectedJobPosition;
    },

    getJobPositionPanel: function() {
        if(!this._fieldsetBasic)
            this._fieldsetBasic = Ext._create('Ext.form.FieldSet', {
                title: 'Cargos',
                collapsible: true,
                layout: {
                    type: 'hbox',
                    align: 'stretchmax',
                    padding: '0 0 6 0'
                },
                items: [
                    this.getAvailableJobPositionGrid(),
                    {
                        width: 35,
                        height: 350,
                        xtype: 'container',
                        frame: true,
                        layout: {
                            type: 'vbox',
                            align: 'stretchmax',
                            padding: '6'
                        },
                        items: [
                            {
                                xtype: 'container',
                                flex: 1
                            },
                            {
                                xtype: 'container',
                                defaults: {
                                    xtype: 'button',
                                    width: 24,
                                    height: 24,
                                    style: {
                                        marginBottom: '5px'
                                    }
                                },
                                items: [
                                    {
                                        iconCls: 'icon-core icon-core-add-all',
                                        scope: this,
                                        handler: function() {this.addAllJobPosition(); }
                                    },
                                    {
                                        iconCls: 'icon-core icon-core-add-selected',
                                        scope: this,
                                        handler: function() {this.addJobPosition(); }
                                    },
                                    {
                                        iconCls: 'icon-core icon-core-remove-selected',
                                        scope: this,
                                        handler: function() {this.removeJobPosition(); }
                                    },
                                    {
                                        iconCls: 'icon-core icon-core-remove-all',
                                        scope: this,
                                        handler: function() {this.removeAllJobPosition(); }
                                    }
                                ]
                            },
                            {
                                xtype: 'container',
                                flex: 1
                            }
                        ]
                    },
                    this.getSelectedJobPositionGrid()
                ]
            });

        return this._fieldsetBasic;
    },

    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                autoScroll: true,
                region: 'center',
                labelAlign: 'top',
                padding: '10',
                items: [
                    {
                        collapsible: true,
                        xtype: 'fieldset',
                        title: 'Quem limita o n° de Adesões por Ata',
                        layout: 'form',
                        labelWidth: 275,
                        items: [
                            {
                                xtype: 'rest-autocompletefield',
                                name: 'management_organ',
                                fieldLabel: 'Órgão Gerenciador',
                                rest: 'rh.generalorgan.Restful',
                                width: 550,
                            },
                        ]
                    },
                    this.getJobPositionPanel()
                ],
                buttons: [
                    {
                        text: 'Salvar',
                        scope: this,
                        handler: this.saveConfiguration
                    },
                    {
                        text: 'Restaurar',
                        scope: this,
                        handler: this.dataReload
                    }
                ]
            });

        return this._formPanel;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        this._values = {};

        Ext.applyIf(
            cfg,
            {
                title: 'Configurações - Gestor de Ata',
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: this.getFormPanel(),
            }
        );

        planning.hiring.configuration.MinuteConfiguration.superclass.constructor.call(this, cfg);
        this.dataReload();
    }
});

/*
 * src: /app/root/planejamento/static/hiring/agreement/Grid.js
 */
Ext._define('planning.hiring.agreement.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'planning.hiring.agreement.Window',

    configOrderToolBar: ['add', 'edit', '-', 'ask', 'report', '-', 'export', '-', 'search', 'filter', '-', 'active'],

    getColumnModel: function () {
        if (!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    { header: 'Status', dataIndex: 'icons', sortable: false, renderer: core.rendererIconGrid, menuDisabled: true, width: 90 },
                    { header: 'Número', dataIndex: 'numero', sortable: true, width: 80 },
                    { header: 'Fiscal', dataIndex: 'main_agreementsupervisors', sortable: true, width: 95 },
                    { header: 'Tipo de Contrato', dataIndex: 'tipo_contrato_display', sortable: true, width: 95 },
                    { header: 'Processo', dataIndex: 'numero_processo', sortable: true, width: 100 },
                    { header: 'Vencimento', dataIndex: 'data_vencimento_flag', sortable: true, width: 70 },
                    { header: 'Serviço', dataIndex: 'objeto_contrato', sortable: true, id: 'autoExpandColumn' },
                ]
            );

        return this._columnModel;
    },

    getReportAction: function () {
        if (!this._reportAction)
            this._reportAction = Ext._create('Ext.Button', {
                text: 'Relatórios',
                iconCls: 'icon-agree icon-agree-application-pdf',
                scope: this,
                menu: [
                    {
                        text: 'Extrato de Pagamentos',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportPaymentStatement').show();
                        }
                    },
                    {
                        text: 'Listagem de Pagamentos',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportPaymentRoll').show();
                        }
                    },
                    {
                        text: 'Saldo de Contrato',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportAgreeBalance').show();
                        }
                    },
                    {
                        text: 'Pagamento por Contrato/OB',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportBankPayment').show();
                        }
                    },
                    {
                        text: 'Fiscais por Contrato',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportAgreeManager').show();
                        }
                    },
                    {
                        text: 'Contratações',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportAgreements').show();
                        }
                    },
                    {
                        text: 'Levantamento de Saldo de Contratos',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportContractBalance').show();
                        }
                    },
                    {
                        text: 'Listagem de Fiscais do Contrato',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportAgreeSupervisor').show();
                        }
                    },
                    {
                        text: 'Contratos por mês de reajuste',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.agreement.ReportMonthReadjustment').show();
                        }
                    },
                ]
            });

        return this._reportAction;
    },

    getExportAction: function () {
        if (!this._exportAction) {
            this._exportAction = Ext._create('Ext.Button', {
                text: 'Exportar XLS',
                iconCls: 'icon-core icon-core-csv',
                scope: this,
                handler: function () {
                    Ext._create('planning.hiring.minutereport.ContratoExportXLS').show();
                }
            });
        }

        return this._exportAction;
    },

    getActiveAction: function () {
        if (!this._activeAction)
            this._activeAction = Ext._create('Ext.form.Checkbox', {
                boxLabel: 'Incluir Inativos',
                scope: this,
                handler: function (c, v) {
                    var store = this.getStore();
                    if (!v) {
                        this.disable();
                        store.removeAll();
                        this.setFilterProperty('status__in', [100, 1, 2, 3], 1000);
                        this.enable();
                    }
                    else {
                        this.disable();
                        store.removeAll();
                        this.setFilterProperty('status__in', [100, 1, 2, 3, 4, 5, 6], 1000);
                        this.enable();
                    }
                }
            });

        return this._activeAction;
    },

    getAskAction: function () {
        if (!this._askAction)
            this._askAction = Ext._create('Ext.Button', {
                text: 'Alterar Status',
                iconCls: 'icon-core icon-core-refresh',
                scope: this,
                menu: [
                    {
                        text: 'Reativar',
                        scope: this,
                        iconCls: 'icon-core icon-core-success',
                        handler: function () {
                            this.execAgreementAction(14);
                        }
                    },
                    {
                        text: 'Cancelar',
                        scope: this,
                        iconCls: 'icon-core icon-core-delete',
                        handler: function () {
                            this.execAgreementAction(15);
                        }
                    },
                    {
                        text: 'Anular',
                        scope: this,
                        iconCls: 'icon-core icon-core-minus',
                        handler: function () {
                            this.execAgreementAction(16);
                        }
                    },
                    {
                        text: 'Rescindir',
                        scope: this,
                        iconCls: 'icon-core icon-core-error',
                        handler: function () {
                            this.execAgreementAction(9);
                        }
                    },
                    {
                        text: 'Finalizar',
                        iconCls: 'icon-core icon-core-run-ok',
                        scope: this,
                        handler: function () {
                            this.execAgreementAction(7)
                        },
                    },  

                ]
            });

        return this._askAction;
    },

    execAgreementAction: function (action) {
        var selected = this.getSelectionModel().getSelected();
        if (selected) {
            var title = 'Alterando status de contratos...';
            var msg = 'Informe uma observação para alterar o(s) contrato(s)?';
            var scope = this;
            var multiline = true;
            var fn_callback = function (btn, text) {
                if (btn == 'cancel') return;

                Ext.Ajax.request({
                    url: core.callAction('PHAAgreementAction', 'finalize_agreement_action'),
                    scope: this,
                    params: {
                        agreements: this.getSelectionModel().getSelections().map(
                            function (record) {
                                return record.get('pk')
                            }
                        ).join(),
                        observation: text ? text : '',
                        type: action // propriedade tipo da classe AcaoContrato
                    },
                    success: function (request) {
                        var rst = Ext.decode(request.responseText);

                        if (rst.success)
                            this.getStore().reload();
                        else
                            Ext.Msg.show({
                                title: 'Alterando contrato',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    }
                });
            };

            Ext.Msg.prompt(title, msg, fn_callback, scope, multiline);

        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um contrato para alterar status.'
            });
        }
    },

    

    toggleType: function(type) {
        if (this.filterType.indexOf(type) >= 0)
            this.filterType.remove(type);
        else
            this.filterType.push(type);

        // this.disable();
        // this.store.removeAll();
        this.setFilterProperty('tipo_contrato__in', this.filterType, 1001);
        // this.enable();
    },

    getAgreementFilter: function() {
        if(!this._agreementFilter)
            this._agreementFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'Contrato',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(1);
                }
            });

        return this._agreementFilter;
    },

    getNEFilter: function(){
        if(!this._NEFilter)
            this._NEFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'NE',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(3);
                }
            });

        return this._NEFilter;
    },

    getRentFilter: function() {
        if(!this._rentFilter)
            this._rentFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'Locação',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(4);
                }
            });

        return this._rentFilter;
    },

    getServicesFilter: function() {
        if(!this._servicesFilter)
            this._servicesFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'Serviços Contínuos',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(5);
                }
            });
        return this._servicesFilter;
    },

    getSupplyFilter: function() {
        if(!this._supplyFilter)
            this._supplyFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'Fornecimento',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(6);
                }
            });

        return this._supplyFilter;
    },

    getExonerationFilter: function() {
            if(!this._exonerationFilter)
            this._exonerationFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'Dispensa',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(7);
                }
            });

        return this._exonerationFilter;
    },

    getLackOfNeedFilter: function() {
        if(!this._lackOfNeedFilter)
            this._lackOfNeedFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'Inexigência',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(8);
                }
            });

        return this._lackOfNeedFilter;
    },

    getNESupplyFilter: function() {
        if(!this._neSupplyFilter)
            this._neSupplyFilter = Ext._create('Ext.menu.CheckItem', {
                text: 'NE Fornecimento',
                scope: this,
                hideOnClick: false,
                checked: (this.filterType.indexOf(1) >= 0) ? true : false,
                handler: function() {
                    this.toggleType(9);
                }
            });

        return this._neSupplyFilter;
    },

    getFilterAction: function() {
        if(!this._filterAction)
            this._filterAction = Ext._create('Ext.Button', {
                text: 'Filtro',
                iconCls: 'icon-patrimonio icon-pat-filter',
                menu: [
                        this.getAgreementFilter(),
                        this.getNEFilter(),
                        this.getRentFilter(),
                        this.getServicesFilter(),
                        this.getSupplyFilter(),
                        this.getExonerationFilter(),
                        this.getLackOfNeedFilter(),
                        this.getNESupplyFilter(),
                ]
            });

        return this._filterAction;
    },

    constructor: function (cfg) {
        cfg = (cfg ? cfg : {});

        if (cfg.filterType)
            this.filterType = cfg.filterType;
        else {
            this.filterType = [1, 3, 4, 5, 6, 7, 8, 9];
        }

        Ext.applyIf(cfg, {
            columnAction: false,
        });

        planning.hiring.agreement.Grid.superclass.constructor.call(this, cfg);
    },
});

core.RestfulGrid.register(
    'planning.hiring.agreement.Restful',
    'planning.hiring.agreement.Grid'
);

/*
 * src: /app/root/planejamento/static/hiring/agreement/Manage.js
 */
Ext._define('planning.hiring.agreement.Manage', {
    extend: 'toolkit.widget.TabPanel',

    getAgreementGrid: function () {
        if (!this._agreementGrid) {
            this._agreementGrid = Ext._create('planning.hiring.agreement.Grid', {
                minHeight: 100,
                region: 'center',
                baseParams: {
                    filter: Ext.encode([{
                        property: 'status__in',
                        value: [100, 1, 2, 3, 4, 5, 6],
                        stage: 1000
                    }])
                }
            });

            this._agreementGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function (selm) {
                    var selection = selm.getSelections();
                    if (selection.length > 0) {
                        this.contrato(selection[0].id);
                    } else {
                        this.contrato(null);
                    }
                }
            });

            this._agreementGrid.getStore().on({
                scope: this,
                load: function () {
                    this.observeContrato();
                }
            });
        }

        return this._agreementGrid;
    },

    getHistoryGrid: function () {
        if (!this._historyGrid)
            this._historyGrid = Ext._create('planning.hiring.agreementaction.Grid', {
                title: 'Histórico',
                gridAutoLoad: false,
            });

        return this._historyGrid;
    },

    getCommitmentNoteGrid: function () {
        if (!this._commitmentNoteGrid)
            this._commitmentNoteGrid = Ext._create('planning.hiring.commitmentnote.Grid', {
                title: 'Nota de Empenho',
                gridAutoLoad: false,
            });

        return this._commitmentNoteGrid;
    },

    getMeterageGrid: function () {
        if (!this._meterageGrid) {
            this._meterageGrid = Ext._create('planning.hiring.meterage.Grid', {
                title: 'Gestão de Pagamentos',
                gridAutoLoad: false,
            });

            this._meterageGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function (selm) {
                    var selection = selm.getSelections();
                    if (selection.length > 0) {
                        this._meterageGrid.pagamento = selection[0].id;
                        this._meterageGrid.contrato = selection[0].json.contrato;
                    } else {
                        this._meterageGrid.pagamento = null;
                    }
                }
            });
        }

        return this._meterageGrid;
    },

    getFeedbackDisplayTilePanel: function () {
        if (!this._feedbackDisplayTilePanel)
            this._feedbackDisplayTilePanel = Ext._create('core.TilePagePanel', {
                title: 'Resumo',
                region: 'east',
                height: '100%',
                width: '40%',
                split: true
            });

        return this._feedbackDisplayTilePanel;
    },

    getTabs: function () {
        if (!this._tabPanel)
            this._tabPanel = Ext._create('Ext.TabPanel', {
                region: 'south',
                split: true,
                activeTab: 0,
                scope: this,
                height: 200,
                items: [
                    this.getHistoryGrid(),
                    this.getCommitmentNoteGrid(),
                    this.getMeterageGrid(),
                ]
            });

        return this._tabPanel;
    },

    contrato: function (value, observe) {
        observe = (observe === undefined ? true : observe);

        if (value !== undefined) {
            this._contrato = value;

            if (observe)
                this.observeContrato();
        }

        return this._contrato;
    },

    observeContrato: function () {
        var value = this.contrato();
        var selected = this.getAgreementGrid().getSelectionModel().getSelected();
        commitmentNoteGrid = this.getCommitmentNoteGrid();
        meterageGrid = this.getMeterageGrid();
        historyGrid = this.getHistoryGrid();
        tilePanel = this.getFeedbackDisplayTilePanel();

        if (value) {
            commitmentNoteGrid.enable();
            commitmentNoteGrid.setParam('contrato', value);
            commitmentNoteGrid.setFilterProperty('contrato', value, 10);

            meterageGrid.enable();
            meterageGrid.setParam('contrato', value);
            meterageGrid.setFilterProperty('contrato', value, 10);

            historyGrid.enable();
            historyGrid.setParam('contrato', value);
            historyGrid.setFilterProperty('contrato', value, 10);

            //Início do trecho referente ao tile
            var rest = this.getAgreementGrid().factoryRestful();
            var mask = new Ext.LoadMask(tilePanel.getEl(), { msg: 'buscando documento...' });

            mask.show();
            rest.rendererDocument(
                value, {
                    scope: this,
                    fn: function (document) {
                        tilePanel.enable();
                        tilePanel.setPageContent(document.content);
                    }
                }, {
                    fn: function (message) {
                        Ext.Msg.show({
                            title: 'Buscando documento',
                            msg: message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                }, {
                    fn: function () {
                        mask.hide();
                    }
                }
            );
            //Fim do trecho dedicado ao tile

        } else {
            commitmentNoteGrid.setParam('contrato', 0);
            commitmentNoteGrid.setFilterProperty('contrato', value, 10, false);
            commitmentNoteGrid.getStore().removeAll();
            commitmentNoteGrid.disable();

            meterageGrid.setParam('contrato', 0);
            meterageGrid.setFilterProperty('contrato', value, 10, false);
            meterageGrid.getStore().removeAll();
            meterageGrid.disable();

            historyGrid.setParam('contrato', 0);
            historyGrid.setFilterProperty('contrato', value, 10, false);
            historyGrid.getStore().removeAll();
            historyGrid.disable();

            tilePanel.setPageContent('');
            tilePanel.disable();
        }
    },

    getGrouping: function () {
        if (!this._grouping)
            this._grouping = Ext._create('Ext.Panel', {
                region: 'center',
                layout: 'border',
                split: true,
                items: [
                    this.getAgreementGrid(),
                    this.getTabs()
                ],
            });

        return this._grouping;
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg, {
                title: 'Gestor de Contratos'
            }
        );

        Ext.apply(
            cfg, {
                layout: 'border',
                items: [
                    this.getGrouping(),
                    this.getFeedbackDisplayTilePanel(cfg),
                ]
            }
        );
        planning.hiring.agreement.Manage.superclass.constructor.call(this, cfg);
        this.observeContrato();
    }
});

/*
 * src: /app/root/planejamento/static/hiring/agreement/Restful.js
 */
Ext._define('planning.hiring.agreement.Restful', {
    extend: 'core.Restful',

    resource: 'PHAAgreement',

    generateFromSolicitations: function(solicitationIdSet, values, successCallback, falureCallaback, commonCallback) {
        values.solicitation_set = solicitationIdSet;
        values.copiar_fiscais = values.copiar_fiscais ? values.copiar_fiscais : 'off';

        this.doRequest(
            this.getRoute(
                'generate_from_solicitations',
                false,
                'POST',
                {
                    params: values,
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success) {
                            core.invokeCallback(
                                successCallback || { fn: Ext.emptyFn },
                                rst
                            );
                        } else {
                            core.invokeCallback(
                                falureCallaback || { fn: Ext.emptyFn },
                                rst.message
                            );
                        }
                    },
                    failure: function(xhr) {
                        core.invokeCallback(
                            falureCallaback || { fn: Ext.emptyFn },
                            'Recurso indisponivel nomento.'
                        );
                    },
                    callback: function(xhr) {
                        core.invokeCallback(commonCallback || { fn: Ext.emptyFn });
                    }
                }
            )
        );
    },

    rendererDocument: function (pk, cbSuccess, cbFailure, cbCallback) {
        var emptyFailure = {
            fn: function (message) {
                Ext.Msg.show({
                    title: 'Buscando documento',
                    msg: message,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        };

        this.doRequest(this.getRoute(
            'renderer_document',
            pk,
            'GET', {
                success: function (xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if (rst.success)
                        core.invokeCallback((cbSuccess || { fn: Ext.emptyFn }), rst.document);
                    else
                        core.invokeCallback((emptyFailure || { fn: Ext.emptyFn }), rst.message);
                },
                failure: function (xhr) {
                    core.invokeCallback((cbFailure || emptyFailure), 'Recurso indisponivel no momento.');
                },
                callback: function () {
                    core.invokeCallback((cbCallback || { fn: Ext.emptyFn }));
                }
            }
        ));
    },

    getFields: function (cfg) {
        if (!this._fields)
            this._fields = planning.hiring.agreement.Restful.superclass.getFields.call(this, cfg).concat([
                {name: "icons"},
                {type: "string",name: "numero"},
                {type: "string",name: "main_agreementsupervisors"},
                {type: "int",name: "tipo_contrato"},
                {type: "string",name: "tipo_contrato_display"},
                {type: "string",name: "numero_processo"},
                {type: "string",name: "numero_processo_mae"},
                {type: "float",name: "valor"},
                {type: "string",name: "objeto_contrato"},
                {type: "string",name: "data_inicio"},
                {type: "string",name: "data_vencimento_flag"},
                {type: "string",name: "data_vencimento"},
                {type: "int",name: "dias_para_aviso"},
                {type: "int",name: "tipo_licitacao"},
                {type: "string",name: "numero_licitacao"},
                {type: "int",name: "tipo_medicao"},
                {type: "int",name: "file"},
                {type: "string",name: "dia_pagamento"},
                {type: "string",name: "numero_pasta"},
                {type: "string",name: "data_publicacao"},
                {type: "string",name: "status"},
                {type: "int",name: "pessoa"},
                {type: "int",name: "responsaveis"},
                {type: "int",name: "solicitation"},
                {type: "int",name: "order"},
                {type: "int",name: "index"},
                {type: "int",name: "reference_month"},
                {type: "string",name: "readjustment_anniversary"},
            ]);

        return this._fields;
    }
});

