/*
 * src: /app/root/planejamento/static/hiring/supervisor/MinuteSupervisorWindow.js
 */
Ext._define('planning.hiring.supervisor.MinuteSupervisorWindow', {
    extend: 'planning.hiring.supervisor.SupervisorWindow',
    rest: 'planning.hiring.supervisor.MinuteSupervisorRestful',
    relatedName: 'minutesupervisors',

    getButtons: function (cfg) {

        if (!this._buttons) {
            this._buttons = [
                {
                    text: 'Fechar',
                    scope: this,
                    handler: this.destroy
                }
            ];

            if (!cfg.disableSave)
                this._buttons = [{
                    text: 'Salvar',
                    scope: this,
                    handler: function () {

                        var me = this;
                        Ext.Ajax.request({
                            scope: this,
                            url: toolkit.util.Normalize.controller_action(
                                'PHMMinute',
                                'verify_minute_validity'
                            ),
                            params: {
                                minute: this.params.minute,
                            },
                            success: function (response) {
                                var obj = Ext.decode(response.responseText);
                                if (obj.success) {
                                    if (obj.after_end_validity)
                                        Ext.Msg.show({
                                            title: 'Ata fora da vigência',
                                            icon: Ext.Msg.QUESTION,
                                            buttons: Ext.Msg.YESNO,
                                            msg: obj.message,
                                            fn: function (bnt) {
                                                if (bnt == 'no') return;
                                                me.save(true);
                                            }
                                        });
                                    else
                                        me.save(true);
                                }
                                else
                                    Ext.Msg.show({
                                        title: 'Ata fora da vigência',
                                        icon: Ext.Msg.ERROR,
                                        buttons: Ext.Msg.OK,
                                        msg: obj.message
                                    });
                            },
                            failure: function (response) {
                                Ext.Msg.show({
                                    title: 'Ocorreu um erro. Tente novamente mais tarde.',
                                    icon: Ext.Msg.INFO,
                                    buttons: Ext.Msg.OK,
                                    msg: rst.message
                                });
                            }

                        });
                    },
                }].concat(this._buttons);

        }

        return this._buttons;
    },
});

/*
 * src: /app/root/planejamento/static/hiring/supervisor/CloseSupervisorWindow.js
 */
Ext._define('planejamento.hiring.supervisor.CloseSupervisorWindow', {
  extend: 'Ext.Window',

  getEndDateField: function() {
      if (!this._endDateField) {
          this._endDateField = Ext._create('Ext.form.DateField', {
              fieldLabel: 'Encerramento',
              name: 'end',
              allowBlank: false,
              value: new Date()
          });
      }

      return this._endDateField;
  },

  getObservationField: function() {
      if (!this._observationField)
          this._observationField = Ext._create('Ext.form.TextArea', {
              fieldLabel: 'Observação',
              name: 'observation',
              allowBlank: 'true',
              height: 250,
              width: 400,
          });

      return this._observationField;
  },

  getFormPanel: function() {
      if (!this._formPanel)
        this._formPanel = Ext._create('Ext.form.FormPanel', {
          frame: true,
          items: [
              this.getEndDateField(),
              this.getObservationField()
          ]
      });

      return this._formPanel;
  },

  getUrlControllerName: function() {
    return core.callAction(this.controllerName, 'close_supervisor');
  },

  commitAction: function() {
      Ext.Ajax.request({
          scope: this,
          url: this.getUrlControllerName(),
          params: {
              pk: this.pk_supervisor,
              end_date: this.getEndDateField().getValue().format('d/m/Y'),
              observation: this.getObservationField().getValue()
          },
          success: function(response, opts) {
              var obj = Ext.decode(response.responseText);

              if (obj.success) {
                  this.supervisorGrid.getStore().reload();
                  Ext.Msg.show({title: 'Encerramento', msg: 'Operação realizada com sucesso', buttons: Ext.Msg.OK});
              } else {
                  Ext.Msg.show({title: 'Atenção!', msg: obj.message, buttons: Ext.Msg.OK});
              }
          },
          failure: function(response, opts) {
              Ext.Msg.show({
                  title: 'Encerrar Fiscal',
                  msg: 'Ocorreu um erro ao encerrar fiscal selecionado',
                  buttons: Ext.Msg.OK
              });
          },
          callback: function() {
              this.destroy();
          }
      });
  },

  toAsk: function() {
      if (!Date.parse(this.getEndDateField().getValue()))
          throw "Informe uma data válida";
      else {
          Ext.Msg.show({
              title: 'Encerrar Fiscal',
              msg: 'Tem certeza que deseja ecerrar Fiscal selecionado?',
              buttons: Ext.Msg.YESNO,
              scope: this,
              fn: function(b) {
                  if (b == 'no')
                      return;
                  else if (b == 'yes')
                      this.commitAction();
              }
          });
      }
  },

  constructor: function(cfg) {
      cfg = (cfg ? cfg : {});

      Ext.apply(cfg, {
          title: 'Encerrar Fiscal',
          autoHeight: true,
          width: 500,
          modal: true,

          items: this.getFormPanel(),

          buttons: [
              {
                  text: 'Encerrar',
                  iconCls: 'icon-agree icon-agree-close-supervisor',
                  scope: this,
                  handler: this.toAsk
              },
              {
                  text: 'Cancelar',
                  // iconCls: '',
                  scope: this,
                  handler: this.destroy
              }
          ]
      });

      planejamento.hiring.supervisor.CloseSupervisorWindow.superclass.constructor.call(this, cfg);
  }
});

/*
 * src: /app/root/planejamento/static/hiring/minute/MinuteRestful.js
 */
Ext._define('planning.hiring.minute.MinuteRestful', {
    extend: 'core.Restful',

    resource: 'PHMMinute',


    rendererDocument: function(pk, cbSuccess, cbFailure, cbCallback) {
        var emptyFailure = {
            fn: function(message) {
                Ext.Msg.show({
                    title: 'Buscando documento',
                    msg: message,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        };

        this.doRequest(this.getRoute('renderer_document', pk, 'GET', {
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if (rst.success)
                        core.invokeCallback((cbSuccess || { fn: Ext.emptyFn }), rst.document);
                    else
                        core.invokeCallback((emptyFailure || { fn: Ext.emptyFn }), rst.message);
                },
                failure: function(xhr) {
                    core.invokeCallback((cbFailure || emptyFailure), 'Recurso indisponível no momento.');
                },
                callback: function() {
                    core.invokeCallback((cbCallback || { fn: Ext.emptyFn }));
                }
            }
        ));
    },

    getFields: function(cfg) {
        if (!this._fields) {
            this._fields = planning.hiring.minute.MinuteRestful.superclass.getFields.call(this, cfg).concat([
                { name: "icons" },
                { type: "string", name: "minute_object" },
                { type: "date", name: "begin_validity", dateFormat: "d/m/Y" },
                { type: "int", name: "modified_by", useNull: true },
                { type: "string", name: "modified_by_unicode" },
                { type: "float", name: "total_amount", useNull: true },
                { type: "string", name: "official_diary" },
                { type: "string", name: "parent_process" },
                { type: "date", name: "end_validity", dateFormat: "d/m/Y" },
                { type: "date", name: "created_at", dateFormat: "d/m/Y H:i" },
                { type: "date", name: "signature_date", dateFormat: "d/m/Y" },
                { type: "date", name: "modified_at", dateFormat: "d/m/Y H:i" },
                { type: "string", name: "number" },
                { type: "int", name: "created_by", useNull: true },
                { type: "string", name: "created_by_unicode" },
                { type: "string", name: "notice_number" },
                { type: "int", name: "management_organ", useNull: true },
                { type: "string", name: "management_organ_unicode" },
                { type: "date", name: "publication_date", dateFormat: "d/m/Y" },
                { type: "int", name: "adhesions_quantity", useNull: true },
                { type: "string", name: "process_number" },
                { type: "string", name: "object_execution" },
                { type: "string", name: "bidding_type" },
                { type: "int", name: "days_for_notice" },
                { type: "int", name: "status", useNull: true },
                { type: "int", name: "provider" },  // Contratados
                { type: "int", name: "enterprise_provider" },  // Estrutura Corporativa
                { type: "string", name: "main_minutesupervisors" },  // Fiscais
            ]);
        }

        return this._fields;
    }
});

