Ext._define('planning.hiring.minutesolicitationmanager.MinuteSolicitationManagerGridAdmin', {
    
    extend: 'planning.hiring.minutesolicitationmanager.MinuteSolicitationManagerGrid',

    configOrderToolBar: ['addsolicitation', 'remove', '-', 'generateOrder', 'situation', 'generateAgreement', 'rebalancing', '-', 'ask', '-', 'report', '-', 'search', 'filter', '->', 'download'],
    
    getAskAction: function () {
        if (!this._askAction)
            this._askAction = Ext._create('Ext.Button', {
                text: 'Alterar Status',
                iconCls: 'icon-core icon-core-refresh',
                scope: this,
                menu: [
                    {
                        text: 'Contratado',
                        scope: this,
                        iconCls: 'icon-core icon-core-document-arrow',
                        handler: function () {
                            this.execActionStatus(7); // MINUTE_SOLICITATION_SITUATION = 7 (Contratado)
                        }
                    },
                ]
            });

        return this._askAction;
    },

    execActionStatus: function (num) {
        var selected = this.getSelectionModel().getSelected();
        if (selected) {
            Ext.Msg.show({
                title: 'Alerta',
                msg: 'Confirma alteração do contrato de '+ selected.get('situation_display')+' para Contratado?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn:function(btn){
                   if (btn == 'no') return;
                    Ext.Ajax.request({
                        url: core.callAction('PHMMinuteSolicitationAction', 'update_status_minute_solicitation'),
                        scope: this,
                        params: {
                            solicitation: this.getSelectionModel().getSelections().map(
                            function (record) {
                                return record.get('pk')
                            }
                            ).join(),
                            action: num
                        },
                        success: function (response) {
                            var obj = Ext.decode(response.responseText);
                            if (obj.success)
                                this.getStore().reload();
                            else
                                Ext.Msg.show({
                                    title: 'Ocorreu um erro',
                                    icon: Ext.Msg.ERROR,
                                    buttons: Ext.Msg.OK,
                                    msg: rst.message
                                });
                        }
                    });
                }
            })
        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um pedido para alterar status.'
            });
        }
    },
});
/*
 * src: /app/root/planejamento/static/hiring/minutesolicitationmanager/MinuteSolicitationManagerManage.js
 */
Ext._define('planning.hiring.minutesolicitationmanager.MinuteSolicitationManagerManage', {
    extend: 'toolkit.widget.TabPanel',


    getMinuteSolicitationManagerGrid: function () {
        if (!this._minuteSolicitationManagerGrid) {
            var me = this;
            this._minuteSolicitationManagerGrid = Ext._create('planning.hiring.minutesolicitationmanager.MinuteSolicitationManagerGrid', {
                region: 'center',
            });

            this._minuteSolicitationManagerGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function (selm) {
                    var selection = selm.getSelections();
                    if (selection.length > 0) {
                        this.solicitation(selection[0].id);
                    } else {
                        this.solicitation(null);
                    }
                }
            });

            this._minuteSolicitationManagerGrid.getStore().on({
                scope: this,
                load: function () {
                    this.observeSolicitation();
                }
            });
        }

        return this._minuteSolicitationManagerGrid;
    },

    getMinuteSolicitationActionGrid: function () {
        if (!this._minuteSolicitationActionGrid) {
            this._minuteSolicitationActionGrid = Ext._create('planning.hiring.minutesolicitationaction.MinuteSolicitationActionGrid', {
                region: 'south',
                gridAutoLoad: false,
                height: 200,
            });
        }

        return this._minuteSolicitationActionGrid;
    },

    getGrouping: function () {
        if (!this._grouping)
            this._grouping = Ext._create('Ext.Panel', {
                region: 'center',
                layout: 'border',
                split: true,
                items: [
                    this.getMinuteSolicitationManagerGrid(),
                    this.getMinuteSolicitationActionGrid()
                ],
            });

        return this._grouping;
    },

    getFeedbackDisplayTilePanel: function () {
        if (!this._feedbackDisplayTilePanel)
            this._feedbackDisplayTilePanel = Ext._create('core.TilePagePanel', {
                title: 'Resumo',
                region: 'east',
                height: '100%',
                width: '40%',
                split: true
            });

        return this._feedbackDisplayTilePanel;
    },

    solicitation: function (value, observe) {
        observe = (observe === undefined ? true : observe);

        if (value !== undefined) {
            this._solicitation = value;

            if (observe)
                this.observeSolicitation();
        }
        return this._solicitation;
    },

    observeSolicitation: function () {
        var value = this.solicitation();
        tilePanel = this.getFeedbackDisplayTilePanel();

        if (value) {
            this.getMinuteSolicitationActionGrid().enable();
            this.getMinuteSolicitationActionGrid().setParam('solicitation', value);
            this.getMinuteSolicitationActionGrid().setFilterProperty('solicitation', value, 10);

            // Início do trecho referente ao tile
            var rest = this.getMinuteSolicitationManagerGrid().factoryRestful();
            var mask = new Ext.LoadMask(tilePanel.getEl(), { msg: 'buscando documento...' });
            mask.show();
            rest.rendererDocument(
                value, {
                    scope: this,
                    fn: function (document) {
                        tilePanel.enable();
                        tilePanel.setPageContent(document.content);
                    }
                }, {
                    fn: function (message) {
                        Ext.Msg.show({
                            title: 'Buscando documento',
                            msg: message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                }, {
                    fn: function () {
                        mask.hide();
                    }
                }
            );
        } else {
            this.getMinuteSolicitationActionGrid().disable();
            this.getMinuteSolicitationActionGrid().setParam('solicitation', 0);
            this.getMinuteSolicitationActionGrid().setFilterProperty('solicitation', 0, 10);

            tilePanel.setPageContent('');
            tilePanel.disable();

        }
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Gestor de Pedidos'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getGrouping(),
                    this.getFeedbackDisplayTilePanel()
                ]
            }
        );

        planning.hiring.minutesolicitationmanager.MinuteSolicitationManagerManage.superclass.constructor.call(this, cfg);
        this.observeSolicitation();
    }
});


